    fn initial_state() -> Self::State {
        // The runtime entry state and the type's `Default` derive are one
        // concept, sourced from one computation (`default_state_id`) so
        // they can never diverge: `<scxml initial>`, or the first sorted
        // state when the initial attribute is unset.
        UnhandledErrorIsObservableState::Idle
    }

    fn is_final_state(state: Self::State) -> bool {
        match state {
            _ => false,
        }
    }

    fn get_parent(state: Self::State) -> Option<Self::State> {
        match state {
            _ => None,
        }
    }

    fn is_compound_state(state: Self::State) -> bool {
        match state {
            _ => false,
        }
    }

    fn is_descendant_of(desc: Self::State, anc: Self::State) -> bool {
        let mut current = desc;
        loop {
            match Self::get_parent(current) {
                None => return false,
                Some(parent) => {
                    if parent == anc {
                        return true;
                    }
                    current = parent;
                }
            }
        }
    }

    fn get_document_order(state: Self::State) -> u32 {
        match state {
            UnhandledErrorIsObservableState::Guarded => 1,
            UnhandledErrorIsObservableState::Idle => 0,
        }
    }

    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            UnhandledErrorIsObservableEvent::Boom => "boom",
            UnhandledErrorIsObservableEvent::ErrorExecution => "error.execution",
            UnhandledErrorIsObservableEvent::Go => "go",
            UnhandledErrorIsObservableEvent::Heard => "heard",
            UnhandledErrorIsObservableEvent::Poke => "poke",
            UnhandledErrorIsObservableEvent::RetryErrorExecution => "retry.error.execution",
            UnhandledErrorIsObservableEvent::Unheard => "unheard",
            UnhandledErrorIsObservableEvent::Whisper => "whisper",
            UnhandledErrorIsObservableEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "boom" => Some(UnhandledErrorIsObservableEvent::Boom),
            "error.execution" => Some(UnhandledErrorIsObservableEvent::ErrorExecution),
            "go" => Some(UnhandledErrorIsObservableEvent::Go),
            "heard" => Some(UnhandledErrorIsObservableEvent::Heard),
            "poke" => Some(UnhandledErrorIsObservableEvent::Poke),
            "retry.error.execution" => Some(UnhandledErrorIsObservableEvent::RetryErrorExecution),
            "unheard" => Some(UnhandledErrorIsObservableEvent::Unheard),
            "whisper" => Some(UnhandledErrorIsObservableEvent::Whisper),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            UnhandledErrorIsObservableState::Guarded => "guarded",
            UnhandledErrorIsObservableState::Idle => "idle",
        }
    }

